// План specs/dashboard.md 3.4, 3.5 (кейсы DB-12, DB-14). Десктоп 1440, admin, компания «test». Только просмотр (@prod-safe).
// Период 90 дней — чтобы у техников были работы. Открытие работы — только переход на её страницу, ничего не меняем.
import { test, expect } from '@playwright/test';
import { ADMIN_STATE } from '../addresses/address-helpers';
import {
  chooseRange, closeBreakdown, ddmmyy, expectRowsMatchRpc, openBreakdown, openDashboardTeam, readBreakdown,
  readBreakdownTotal, readTeamRows, teamWidget, trackDashboardRpc,
} from './team-performance-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Дашборд, Team Performance: разбивка по технику (#5814749d)', () => {
  test('Desktop Team Performance EN: click on each technician opens list of jobs (number, client, date, amount) whose total equals the row #5814749d @desktop @prod-safe', async ({ page }) => {
    const rpc = trackDashboardRpc(page);
    await openDashboardTeam(page, 'en');
    await rpc.teamFor(30);
    await chooseRange(page, teamWidget(page, 'en'), 'en', 90, 'team');
    const team = await rpc.teamFor(90);
    await expectRowsMatchRpc(page, 'en', team);
    const rows = await readTeamRows(page, 'en');
    expect(rows.length, 'в компании «test» за 90 дней есть техники с работами').toBeGreaterThan(0);

    for (const row of rows) {
      const dlg = await openBreakdown(page, 'en', row);
      // Подзаголовок: «Completed jobs · dd/mm/yy – dd/mm/yy» = выбранный период.
      await expect(dlg).toContainText(`Completed jobs · ${ddmmyy(team.from)} – ${ddmmyy(team.to)}`);

      const jobs = await readBreakdown(dlg);
      for (const j of jobs) {
        expect(j.href, `ссылка на работу: ${j.text}`).toMatch(/^\/JobDetail\?id=[0-9a-f-]{36}$/);
        expect(j.jobNo, `номер работы: ${j.text}`).toMatch(/^[A-Z]+-\d+$/);
        expect(j.date, `дата завершения: ${j.text}`).toMatch(/^\d{2}\/\d{2}\/\d{2}$/);
        expect(Number.isFinite(j.cents), `сумма работы: ${j.text}`).toBe(true);
      }
      // Итог «Total · N $X» = строке виджета и сумме работ в списке («מה רצוי»: אפשרות לראות פירוט).
      const total = await readBreakdownTotal(dlg);
      expect(total, `итог разбивки ${row.name} = строка виджета`).toEqual({ count: row.jobs, cents: row.cents });
      expect(jobs.reduce((s, j) => s + j.cents, 0), `сумма работ ${row.name} = итог`).toBe(row.cents);
      await closeBreakdown(dlg);
    }
  });

  test('Desktop Team Performance EN: click on a job in technician breakdown opens that job page #5814749d @desktop @prod-safe', async ({ page }) => {
    const rpc = trackDashboardRpc(page);
    await openDashboardTeam(page, 'en');
    await rpc.teamFor(30);
    await chooseRange(page, teamWidget(page, 'en'), 'en', 90, 'team');
    await expectRowsMatchRpc(page, 'en', await rpc.teamFor(90));
    const [row] = await readTeamRows(page, 'en');
    expect(row, 'есть хотя бы один техник с работами за 90 дней').toBeTruthy();

    const dlg = await openBreakdown(page, 'en', row);
    const [job] = await readBreakdown(dlg);
    await dlg.getByRole('listitem').first().getByRole('link').click();
    await page.waitForURL((u) => `${u.pathname}${u.search}` === job.href);
    await expect(page.getByText(job.jobNo).first()).toBeVisible();
  });
});
